<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarRemitentesReporte, exportarReporte, listarReporte } from '../services/reportes'
import type { ReportDoc, ReportFilters } from '../interfaces/reportes.interface'
import type { CatalogOption } from '../../interfaces/documento'
const filters=reactive<ReportFilters>({criterio:'',tipo_documento_id:0,remitente_id:0,fecha_inicio:'',fecha_fin:'',page:1}),items=ref<ReportDoc[]>([]),tipos=ref<CatalogOption[]>([]),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),exporting=ref(''),error=ref(''),searched=ref(false),remitenteText=ref(''),remitentes=ref<Array<{id:number;text:string}>>([]),selectedRemitente=ref('')
async function load(page=1){filters.page=page;loading.value=true;searched.value=true;error.value='';try{const r=await listarReporte(filters);items.value=r.data;tipos.value=r.tipos_documento;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo generar el reporte.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',tipo_documento_id:0,remitente_id:0,fecha_inicio:'',fecha_fin:'',page:1});remitenteText.value='';selectedRemitente.value='';items.value=[];searched.value=false}
async function searchSender(){if(remitenteText.value.length<2){remitentes.value=[];return}try{remitentes.value=await buscarRemitentesReporte(remitenteText.value)}catch{remitentes.value=[]}}
function selectSender(r:{id:number;text:string}){filters.remitente_id=r.id;selectedRemitente.value=r.text;remitenteText.value=r.text;remitentes.value=[]}
async function download(type:'excel'|'pdf'){exporting.value=type;error.value='';try{await exportarReporte(type,filters)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo exportar.'}finally{exporting.value=''}}
function number(d:ReportDoc){return d.numero_completo||d.numero||`Documento #${d.id}`}
function date(v?:string|null){return v?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
onMounted(async()=>{try{const r=await listarReporte(filters);tipos.value=r.tipos_documento}catch{/* Se reintenta al buscar. */}})
</script>
<template><div class="report"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Reportes y firma / Documentos</nav><header class="hero"><div class="mark">RPT</div><div><small>Reportes</small><h1>Reporte de documentos</h1><p>Consulta documentos internos y externos y exporta el resultado.</p></div><strong v-if="searched">{{pagination.total}} registros</strong></header><form class="filters" @submit.prevent="load()"><div class="grid"><label><span>Búsqueda general</span><input v-model.trim="filters.criterio" placeholder="Número, asunto o código único"></label><label><span>Tipo documental</span><select v-model="filters.tipo_documento_id"><option :value="0">Todos</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label class="sender"><span>Remitente</span><input v-model.trim="remitenteText" placeholder="Nombre, DNI o RUC" @input="filters.remitente_id=0;selectedRemitente='';searchSender()"><ul v-if="remitentes.length"><li v-for="r in remitentes" :key="r.id" @click="selectSender(r)">{{r.text}}</li></ul></label><label><span>Fecha inicial</span><input v-model="filters.fecha_inicio" type="date"></label><label><span>Fecha final</span><input v-model="filters.fecha_fin" type="date"></label></div><footer><button>Consultar</button><button type="button" class="clear" @click="clear">Limpiar</button><span></span><button type="button" class="excel" :disabled="!searched||exporting!==''" @click="download('excel')">{{exporting==='excel'?'Generando…':'Exportar Excel'}}</button><button type="button" class="pdf" :disabled="!searched||exporting!==''" @click="download('pdf')">{{exporting==='pdf'?'Generando…':'Exportar PDF'}}</button></footer></form><div v-if="error" class="notice error">{{error}}</div><div v-else-if="loading" class="notice">Generando reporte…</div><div v-else-if="searched&&!items.length" class="notice">No se encontraron documentos con estos filtros.</div><div v-else-if="!searched" class="notice intro"><b>Configura los filtros del reporte</b><span>Puedes consultar todos los documentos o limitar el resultado por período.</span></div><section v-else class="table"><table><thead><tr><th>ID / Código</th><th>Documento</th><th>Asunto</th><th>Remitente</th><th>Instancia emisora</th><th>Estado</th><th>Prioridad</th><th>Registro</th></tr></thead><tbody><tr v-for="d in items" :key="d.id"><td><b>#{{d.id}}</b><small>CU {{d.codigo_unico||d.historial?.[0]?.codigounico||'—'}}</small></td><td><b>{{number(d)}}</b><small>{{d.tipo_documento?.nombre||'—'}}</small></td><td>{{d.asunto}}</td><td>{{d.remitente||'—'}}</td><td>{{d.instancia_emisora||d.historial?.[0]?.instancia_origen?.nombre||'—'}}</td><td><span class="status">{{d.estado||d.historial?.[0]?.estado||'—'}}</span></td><td>{{d.prioridad||'Normal'}}</td><td>{{date(d.created_at)}}</td></tr></tbody></table></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer></div></template>
<style scoped>
.report{--accent:#2878d0;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small{color:var(--accent);font-size:.62rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero>strong{margin-left:auto;padding:7px 9px;border-radius:15px;color:var(--accent);background:#eaf3fc;font-size:.62rem}.filters{margin:16px 0;padding:18px;border:1px solid #e2e7ea;border-radius:11px;background:#fff}.grid{display:grid;grid-template-columns:1.3fr 1fr 1.3fr 1fr 1fr;gap:9px}label span{display:block;margin-bottom:6px;color:#66737a;font-size:.62rem}input,select{width:100%;height:40px;padding:0 9px;border:1px solid #dae2e6;border-radius:7px;background:#fff;font:inherit;font-size:.67rem}.sender{position:relative}.sender ul{position:absolute;z-index:3;left:0;right:0;margin:2px 0;padding:5px;list-style:none;border:1px solid #dce3e7;border-radius:7px;background:#fff;box-shadow:0 8px 20px #1b344422}.sender li{padding:7px;font-size:.62rem;cursor:pointer}.filters footer{margin-top:14px;display:flex;gap:6px}.filters footer span{flex:1}.filters button,.pagination button{padding:8px 12px;border:1px solid var(--accent);border-radius:7px;color:#fff;background:var(--accent);font-size:.62rem}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}.excel{border-color:#27885f!important;background:#27885f!important}.pdf{border-color:#bd5050!important;background:#bd5050!important}.notice{padding:45px;display:flex;align-items:center;flex-direction:column;gap:6px;text-align:center;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.69rem}.notice.error{color:#a13f43}.table{overflow:auto;border:1px solid #dfe6e9;border-radius:11px;background:#fff}table{width:100%;min-width:1050px;border-collapse:collapse}th,td{padding:11px;text-align:left;border-top:1px solid #edf0f2;font-size:.61rem}th{border:0;color:#738087;background:#f4f7f8;text-transform:uppercase;font-size:.55rem}td b,td small{display:block}td small{color:#89959b}.status{padding:4px 6px;border-radius:12px;color:#28699d;background:#e6f1fa;font-size:.54rem}.pagination{padding:18px;display:flex;justify-content:center;align-items:center;gap:12px;font-size:.64rem}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}.filters footer{flex-wrap:wrap}.filters footer span{display:none}}@media(max-width:580px){.grid{grid-template-columns:1fr}.hero{flex-wrap:wrap}.filters footer button{flex:1}}
</style>
